/**
 * Docker Compose generator for self-hosted FeltDB deployments
 *
 * Generates:
 * - docker-compose.yml with three locally buildable services
 * - Dockerfiles for the FeltDB server, application, and Studio
 * - .dockerignore for optimized builds
 * - Environment configuration
 */
export function generateDockerCompose(config) {
    return `services:
  feltdb:
    image: \${FELTDB_IMAGE:-${config.appName.toLowerCase().replace(/[^a-z0-9]/g, '-')}-feltdb:${config.version}}
    build:
      context: .
      dockerfile: Dockerfile.feltdb
      args:
        FELTDB_VERSION: ${config.version}
    container_name: \${COMPOSE_PROJECT_NAME}-feltdb
    environment:
      FELTDB_APP_NAME: \${FELTDB_APP_NAME:-${config.appName}}
      FELTDB_APP_ID: \${FELTDB_APP_ID:-${config.appId}}
      FELTDB_VERSION: \${FELTDB_VERSION:-${config.version}}
      FELTDB_ENVIRONMENT: \${FELTDB_ENVIRONMENT:-staging}
      FELTDB_PEERS: \${FELTDB_PEERS:-}
      FELTDB_MASTER_KEY: \${FELTDB_MASTER_KEY}
      NODE_ENV: \${NODE_ENV:-production}
    ports:
      - "\${FELTDB_API_PORT:-${config.port}}:7700"
    command:
      - feltdb-server
      - --host
      - 0.0.0.0
      - --port
      - "7700"
      - --namespace
      - \${FELTDB_APP_ID:-${config.appId}}
      - --data
      - /data/feltdb.log
      - --allow-origin
      - http://localhost:\${APP_PORT:-5173}
      - --allow-origin
      - http://localhost:\${STUDIO_PORT:-${config.studioPort}}
    volumes:
      - feltdb_data:/data
      - ./feltdb.flow:/app/feltdb.flow:ro
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost:7700/health"]
      interval: 10s
      timeout: 5s
      retries: 3
      start_period: 30s
    restart: unless-stopped
    networks:
      - feltdb_network
    labels:
      app.feltdb/component: "database"
      app.feltdb/version: "${config.version}"

  app:
    image: \${APP_IMAGE:-${config.appName.toLowerCase().replace(/[^a-z0-9]/g, '-')}:latest}
    build:
      context: .
      dockerfile: Dockerfile
      args:
        NODE_ENV: production
    container_name: \${COMPOSE_PROJECT_NAME}-app
    environment:
      FELTDB_API_URL: http://feltdb:7700
      FELTDB_APP_NAME: \${FELTDB_APP_NAME:-${config.appName}}
      NODE_ENV: \${NODE_ENV:-production}
    ports:
      - "\${APP_PORT:-5173}:80"
    depends_on:
      feltdb:
        condition: service_healthy
    healthcheck:
      test: ["CMD", "wget", "-q", "--spider", "http://localhost/"]
      interval: 10s
      timeout: 5s
      retries: 3
      start_period: 30s
    restart: unless-stopped
    networks:
      - feltdb_network
    labels:
      app.feltdb/component: "application"
      app.feltdb/version: "${config.version}"

  studio:
    image: \${STUDIO_IMAGE:-${config.appName.toLowerCase().replace(/[^a-z0-9]/g, '-')}-studio:${config.version}}
    build:
      context: .
      dockerfile: Dockerfile.studio
      args:
        FELTDB_VERSION: ${config.version}
    container_name: \${COMPOSE_PROJECT_NAME}-studio
    environment:
      FELTDB_API_URL: \${FELTDB_PUBLIC_URL:-http://127.0.0.1:${config.port}}
      APP_URL: \${APP_PUBLIC_URL:-http://localhost:5173/}
      FELTDB_NAMESPACE: \${FELTDB_APP_ID:-${config.appId}}
    ports:
      - "\${STUDIO_PORT:-${config.studioPort}}:8000"
    depends_on:
      - feltdb
      - app
    networks:
      - feltdb_network
    labels:
      app.feltdb/component: "studio"

networks:
  feltdb_network:
    driver: bridge
    labels:
      app.feltdb/network: "internal"

volumes:
  feltdb_data:
    driver: local
    labels:
      app.feltdb/data: "durable-operations-log"
`;
}
export function generateFeltDBDockerfile(config) {
    return `# Build the matching FeltDB server without adding engine source to the application.
FROM rust:1.96-alpine AS builder
RUN apk add --no-cache nodejs npm pkgconf openssl-dev musl-dev
WORKDIR /source
ARG FELTDB_VERSION=${config.version}
RUN npm install --global "create-feltdb@\${FELTDB_VERSION}" \
 && cp -R "\$(npm root --global)/create-feltdb/dist/server-source/." /source/
RUN cargo build -p feltdb-server --release --locked

FROM alpine:3.22
RUN apk add --no-cache ca-certificates curl tini
COPY --from=builder /source/target/release/feltdb-server /usr/local/bin/feltdb-server
RUN adduser -D -u 1000 feltdb && mkdir -p /data && chown feltdb:feltdb /data
USER feltdb
EXPOSE 7700
HEALTHCHECK --interval=10s --timeout=5s --start-period=30s --retries=3 CMD curl -fsS http://127.0.0.1:7700/health || exit 1
ENTRYPOINT ["/sbin/tini", "--"]
CMD ["feltdb-server", "--host", "0.0.0.0", "--port", "7700", "--namespace", "${config.appId}", "--data", "/data/feltdb.log", "--allow-origin", "http://localhost:5173", "--allow-origin", "http://localhost:${config.studioPort}"]
`;
}
export function generateStudioDockerfile(config) {
    return `# FeltDB Studio served by the same version as this generated project.
FROM node:22-alpine
ARG FELTDB_VERSION=${config.version}
RUN npm install --global "@feltdb/core@\${FELTDB_VERSION}" && npm cache clean --force
WORKDIR /project
COPY feltdb.flow ./feltdb.flow
EXPOSE 8000
CMD ["sh", "-c", "feltdb studio --host 0.0.0.0 --port 8000 --namespace \"\${FELTDB_NAMESPACE}\" --runtime self-hosted --connect \"\${FELTDB_API_URL}\" --app-url \"\${APP_URL}\" --no-open"]
`;
}
export function generateDockerfile(config, framework) {
    const buildCommand = 'npm run build';
    return `# FeltDB Application Container
# Multi-stage build for optimized production image

FROM node:20-alpine AS builder

WORKDIR /app

# Install dependencies
COPY package.json package-lock.json ./
RUN npm ci && npm cache clean --force

# Copy source
COPY . .

# Build application
RUN ${buildCommand}

FROM nginx:1.27-alpine
COPY --from=builder /app/dist /usr/share/nginx/html
EXPOSE 80
`;
}
export function generateDockerIgnore() {
    return `node_modules
npm-debug.log
dist
build
.git
.gitignore
.env
.env.local
.env.*.local
.DS_Store
*.log
.feltdb
.nextc
.next
coverage
.nyc_output
.cache
.turbo
`;
}
export function generateDotEnvLocal(config, masterKey = '') {
    return `# Docker Compose Environment
# Generated by create-feltdb for \${config.appName}

COMPOSE_PROJECT_NAME=${config.appName.toLowerCase().replace(/[^a-z0-9]/g, '-')}

# FeltDB Configuration
FELTDB_APP_NAME=${config.appName}
FELTDB_APP_ID=${config.appId}
FELTDB_VERSION=${config.version}
FELTDB_ENVIRONMENT=staging
FELTDB_API_PORT=${config.port}
FELTDB_REPLICATION_PORT=${config.replicationPort}
FELTDB_PEERS=
FELTDB_MASTER_KEY=${masterKey}

# Application Configuration
APP_PORT=3000
FELTDB_API_URL=http://feltdb:7700

# Studio Configuration
STUDIO_PORT=${config.studioPort}

`;
}
export function generateHealthCheckScript() {
    return `#!/bin/bash

# Multi-service health check orchestration
# Ensures all services are ready before marking deployment as healthy

set -e

TIMEOUT=60
ELAPSED=0
INTERVAL=2

echo "[Health Check] Starting orchestration check (timeout: \${TIMEOUT}s)"

# Wait for FeltDB
echo "[Health Check] Checking FeltDB service..."
while [ \$ELAPSED -lt \$TIMEOUT ]; do
  if curl -s -f http://feltdb:7700/health > /dev/null 2>&1; then
    STATE=\$(curl -s http://feltdb:7700/health | grep -o '"state":"[^"]*' | cut -d'"' -f4)
    if [ "\$STATE" = "ready" ] || [ "\$STATE" = "recovering" ]; then
      echo "[Health Check] FeltDB is \$STATE"
      break
    fi
  fi
  sleep \$INTERVAL
  ELAPSED=\$((ELAPSED + INTERVAL))
done

if [ \$ELAPSED -ge \$TIMEOUT ]; then
  echo "[Health Check] FAILED: FeltDB did not respond within timeout"
  exit 1
fi

# Wait for application
echo "[Health Check] Checking application service..."
ELAPSED=0
while [ \$ELAPSED -lt \$TIMEOUT ]; do
  if curl -s -f http://app:3000/health > /dev/null 2>&1; then
    echo "[Health Check] Application is ready"
    break
  fi
  sleep \$INTERVAL
  ELAPSED=\$((ELAPSED + INTERVAL))
done

if [ \$ELAPSED -ge \$TIMEOUT ]; then
  echo "[Health Check] FAILED: Application did not respond within timeout"
  exit 1
fi

echo "[Health Check] All services healthy - deployment ready"
exit 0
`;
}
